CIVIL = ROOT / "src" / "CE.Tools.Civil3D"
PROJECT = CIVIL / "ProjectStyleCenterCommands.cs"
DISCOVERY = CIVIL / "CivilStyleDiscovery.cs"
SEWER = CIVIL / "SewerProductionCommands.cs"
LABELS = CIVIL / "SewerNetworkLabelCommands.cs"
CORE_TESTS = ROOT / ".github" / "workflows" / "core-tests.yml"
VALIDATOR = ROOT / "scripts" / "Validate-CivilStyleCatalogueAndSewerLabels.py"
HELPER = CIVIL / "CivilStyleCatalogV2.cs"

HELPER_SOURCE = 'using System;\nusing System.Collections;\nusing System.Collections.Generic;\nusing System.Globalization;\nusing System.Linq;\nusing System.Reflection;\nusing System.Runtime.CompilerServices;\nusing Autodesk.AutoCAD.ApplicationServices;\nusing Autodesk.AutoCAD.DatabaseServices;\nusing Autodesk.Civil.ApplicationServices;\nusing Autodesk.Civil.DatabaseServices.Styles;\n\nnamespace CETools.Civil3D\n{\n    /// <summary>\n    /// Strict Civil 3D style catalogue used by production dialogs.\n    /// Only real StyleBase objects are returned; Aecc display representations,\n    /// views and other named database objects are deliberately excluded.\n    /// </summary>\n    internal static class CivilStyleCatalogV2\n    {\n        internal const string DrawingDefault = "<Use drawing default>";\n\n        private static readonly IDictionary<string, string[]> KnownPaths =\n            new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)\n            {\n                { "Alignment Style", new[] { "AlignmentStyles" } },\n                { "Alignment Label Set Style", new[] { "LabelSetStyles.AlignmentLabelSetStyles" } },\n                { "Alignment Label Style", new[] { "LabelStyles.AlignmentLabelStyles" } },\n                { "Profile Style", new[] { "ProfileStyles" } },\n                { "Profile Label Set Style", new[] { "LabelSetStyles.ProfileLabelSetStyles" } },\n                { "Profile Label Style", new[] { "LabelStyles.ProfileLabelStyles" } },\n                { "Profile View Style", new[] { "ProfileViewStyles" } },\n                { "Profile View Band Set Style", new[] { "ProfileViewBandSetStyles" } },\n                { "Profile View Label Style", new[] { "LabelStyles.ProfileViewLabelStyles" } },\n                { "Surface Style", new[] { "SurfaceStyles" } },\n                { "Surface Label Style", new[] { "LabelStyles.SurfaceLabelStyles" } },\n                { "Point Style", new[] { "PointStyles" } },\n                { "Point Label Style", new[] { "LabelStyles.PointLabelStyles" } },\n                { "Feature Line Style", new[] { "FeatureLineStyles" } },\n                { "Feature Line Label Style", new[] { "LabelStyles.FeatureLineLabelStyles" } },\n                { "Parcel Style", new[] { "ParcelStyles" } },\n                { "Parcel Label Style", new[] { "LabelStyles.ParcelLabelStyles" } },\n                { "Catchment Style", new[] { "CatchmentStyles" } },\n                { "Catchment Label Style", new[] { "LabelStyles.CatchmentLabelStyles" } },\n                { "Grading Style", new[] { "GradingStyles" } },\n                { "Corridor Style", new[] { "CorridorStyles" } },\n                { "Code Set Style", new[] { "CodeSetStyles" } },\n                { "Assembly Style", new[] { "AssemblyStyles" } },\n                { "Pipe Style", new[] { "PipeStyles" } },\n                { "Pipe Label Style", new[] {\n                    "LabelStyles.PipeLabelStyles.PlanProfileLabelStyles",\n                    "LabelStyles.PipeLabelStyles.PlanLabelStyles"\n                } },\n                { "Structure Style", new[] { "StructureStyles" } },\n                { "Structure Label Style", new[] {\n                    "LabelStyles.StructureLabelStyles.LabelStyles",\n                    "LabelStyles.StructureLabelStyles"\n                } },\n                { "Pipe Rule Set", new[] { "PipeRuleSetStyles" } },\n                { "Structure Rule Set", new[] { "StructureRuleSetStyles" } },\n                { "Pressure Pipe Style", new[] {\n                    "PressurePipeStyles",\n                    "PressureNetworkStyles.PressurePipeStyles"\n                } },\n                { "Pressure Pipe Label Style", new[] {\n                    "LabelStyles.PressurePipeLabelStyles.PlanProfileLabelStyles",\n                    "LabelStyles.PressurePipeLabelStyles",\n                    "PressureNetworkStyles.PressurePipeLabelStyles"\n                } },\n                { "Fitting Style", new[] {\n                    "FittingStyles",\n                    "PressureNetworkStyles.FittingStyles"\n                } },\n                { "Fitting Label Style", new[] {\n                    "LabelStyles.PressureFittingLabelStyles",\n                    "LabelStyles.FittingLabelStyles"\n                } },\n                { "Appurtenance Style", new[] {\n                    "AppurtenanceStyles",\n                    "PressureNetworkStyles.AppurtenanceStyles"\n                } },\n                { "Appurtenance Label Style", new[] {\n                    "LabelStyles.PressureAppurtenanceLabelStyles",\n                    "LabelStyles.AppurtenanceLabelStyles"\n                } },\n                { "Section Style", new[] { "SectionStyles" } },\n                { "Section Label Set Style", new[] { "LabelSetStyles.SectionLabelSetStyles" } },\n                { "Section Label Style", new[] { "LabelStyles.SectionLabelStyles" } },\n                { "Section View Style", new[] { "SectionViewStyles" } },\n                { "Section View Band Set Style", new[] { "SectionViewBandSetStyles" } },\n                { "Section View Label Style", new[] { "LabelStyles.SectionViewLabelStyles" } },\n                { "Sample Line Style", new[] { "SampleLineStyles" } },\n                { "Sample Line Label Style", new[] { "LabelStyles.SampleLineLabelStyles" } },\n                { "Mass Haul View Style", new[] { "MassHaulViewStyles" } },\n                { "Mass Haul Line Style", new[] { "MassHaulLineStyles" } },\n                { "Marker Style", new[] { "MarkerStyles" } },\n                { "Alignment Table Style", new[] { "TableStyles.AlignmentTableStyles" } },\n                { "Parcel Table Style", new[] { "TableStyles.ParcelTableStyles" } },\n                { "Point Table Style", new[] { "TableStyles.PointTableStyles" } },\n                { "Pipe Table Style", new[] { "TableStyles.PipeTableStyles" } },\n                { "Structure Table Style", new[] { "TableStyles.StructureTableStyles" } },\n                { "Surface Table Style", new[] { "TableStyles.SurfaceTableStyles" } }\n            };\n\n        internal static Dictionary<string, List<string>> ReadProjectCatalogue(\n            Document document,\n            IEnumerable<string> selectionKeys)\n        {\n            var result = new Dictionary<string, List<string>>(\n                StringComparer.OrdinalIgnoreCase);\n            foreach (string key in selectionKeys ?? Enumerable.Empty<string>())\n                result[key] = new List<string> { DrawingDefault };\n\n            if (document == null) return result;\n            CivilDocument civilDocument = CivilApplication.ActiveDocument;\n            if (civilDocument == null) return result;\n            object stylesRoot = ReadProperty(civilDocument, "Styles");\n            if (stylesRoot == null) return result;\n\n            using (Transaction transaction =\n                document.Database.TransactionManager.StartTransaction())\n            {\n                foreach (KeyValuePair<string, string[]> entry in KnownPaths)\n                {\n                    List<string> target;\n                    if (!result.TryGetValue(entry.Key, out target)) continue;\n                    foreach (string path in entry.Value)\n                    {\n                        object root = ReadPropertyPath(stylesRoot, path);\n                        if (root == null) continue;\n                        var ids = new HashSet<ObjectId>();\n                        CollectStyleIds(\n                            root,\n                            transaction,\n                            0,\n                            new HashSet<object>(ReferenceComparer.Instance),\n                            ids);\n                        foreach (ObjectId id in ids)\n                        {\n                            StyleBase style = OpenStyle(id, transaction);\n                            if (style != null && !string.IsNullOrWhiteSpace(style.Name))\n                                target.Add(style.Name.Trim());\n                        }\n                    }\n                }\n            }\n\n            // Newly imported styles may be visible in the DWG dictionaries before\n            // every Civil 3D 2023 managed collection refreshes. This fallback is\n            // safe because CivilStyleDiscovery now accepts StyleBase objects only.\n            IDictionary<string, List<string>> databaseCatalogue =\n                CivilStyleDiscovery.ReadCatalogue(document.Database);\n            foreach (KeyValuePair<string, List<string>> entry in databaseCatalogue)\n            {\n                List<string> target;\n                if (result.TryGetValue(entry.Key, out target))\n                    target.AddRange(entry.Value);\n            }\n\n            foreach (string key in result.Keys.ToList())\n            {\n                List<string> ordered = result[key]\n                    .Where(value => !string.IsNullOrWhiteSpace(value))\n                    .Where(value => !LooksLikeRuntimeClassName(value))\n                    .Distinct(StringComparer.OrdinalIgnoreCase)\n                    .OrderBy(value => value, StringComparer.CurrentCultureIgnoreCase)\n                    .ToList();\n                ordered.RemoveAll(value => string.Equals(\n                    value, DrawingDefault, StringComparison.OrdinalIgnoreCase));\n                ordered.Insert(0, DrawingDefault);\n                result[key] = ordered;\n            }\n            return result;\n        }\n\n        internal static IList<string> ReadNames(\n            Database database,\n            object collection)\n        {\n            return ReadNames(database, collection, string.Empty);\n        }\n\n        internal static IList<string> ReadNames(\n            Database database,\n            object collection,\n            string category)\n        {\n            var names = new List<string>();\n            if (database == null) return names;\n            using (Transaction transaction =\n                database.TransactionManager.StartTransaction())\n            {\n                foreach (ObjectId id in ReadObjectIds(collection, transaction))\n                {\n                    StyleBase style = OpenStyle(id, transaction);\n                    if (style != null &&\n                        !string.IsNullOrWhiteSpace(style.Name) &&\n                        !LooksLikeRuntimeClassName(style.Name))\n                    {\n                        names.Add(style.Name.Trim());\n                    }\n                }\n            }\n\n            if (names.Count == 0 && !string.IsNullOrWhiteSpace(category))\n            {\n                IDictionary<string, List<string>> fallback =\n                    CivilStyleDiscovery.ReadCatalogue(database);\n                List<string> values;\n                if (fallback.TryGetValue(category, out values))\n                    names.AddRange(values);\n            }\n\n            return names\n                .Where(value => !string.IsNullOrWhiteSpace(value))\n                .Where(value => !LooksLikeRuntimeClassName(value))\n                .Distinct(StringComparer.OrdinalIgnoreCase)\n                .OrderBy(value => value, StringComparer.CurrentCultureIgnoreCase)\n                .ToList();\n        }\n\n        internal static IList<ObjectId> ReadObjectIds(\n            object collection,\n            Transaction transaction)\n        {\n            var ids = new HashSet<ObjectId>();\n            CollectStyleIds(\n                collection,\n                transaction,\n                0,\n                new HashSet<object>(ReferenceComparer.Instance),\n                ids);\n            return ids\n                .Where(id => !id.IsNull && !id.IsErased)\n                .OrderBy(id => id.Handle.Value)\n                .ToList();\n        }\n\n        internal static IList<object> Enumerate(object collection)\n        {\n            var result = new List<object>();\n            if (collection == null || collection is string) return result;\n\n            IEnumerable enumerable = collection as IEnumerable;\n            if (enumerable != null)\n            {\n                try\n                {\n                    foreach (object item in enumerable) result.Add(item);\n                }\n                catch\n                {\n                    result.Clear();\n                }\n                if (result.Count > 0) return result;\n            }\n\n            foreach (string methodName in new[]\n            {\n                "GetObjectIds", "GetItemIds", "GetIds"\n            })\n            {\n                try\n                {\n                    MethodInfo method = collection.GetType().GetMethod(\n                        methodName,\n                        BindingFlags.Public | BindingFlags.Instance,\n                        null,\n                        Type.EmptyTypes,\n                        null);\n                    object value = method == null\n                        ? null\n                        : method.Invoke(collection, null);\n                    IEnumerable values = value as IEnumerable;\n                    if (values == null) continue;\n                    foreach (object item in values) result.Add(item);\n                    if (result.Count > 0) return result;\n                }\n                catch\n                {\n                    result.Clear();\n                }\n            }\n\n            try\n            {\n                MethodInfo getEnumerator = collection.GetType().GetMethod(\n                    "GetEnumerator",\n                    BindingFlags.Public | BindingFlags.NonPublic |\n                    BindingFlags.Instance,\n                    null,\n                    Type.EmptyTypes,\n                    null);\n                IEnumerator iterator = getEnumerator == null\n                    ? null\n                    : getEnumerator.Invoke(collection, null) as IEnumerator;\n                if (iterator != null)\n                {\n                    while (iterator.MoveNext()) result.Add(iterator.Current);\n                    if (result.Count > 0) return result;\n                }\n            }\n            catch\n            {\n                result.Clear();\n            }\n\n            try\n            {\n                PropertyInfo countProperty = collection.GetType().GetProperty(\n                    "Count",\n                    BindingFlags.Public | BindingFlags.Instance);\n                int count = countProperty == null\n                    ? 0\n                    : Convert.ToInt32(\n                        countProperty.GetValue(collection, null),\n                        CultureInfo.InvariantCulture);\n                PropertyInfo indexer = collection.GetType()\n                    .GetProperties(BindingFlags.Public | BindingFlags.Instance)\n                    .FirstOrDefault(property =>\n                    {\n                        ParameterInfo[] parameters =\n                            property.GetIndexParameters();\n                        return parameters.Length == 1 &&\n                            property.GetGetMethod() != null &&\n                            IsIntegral(parameters[0].ParameterType);\n                    });\n                MethodInfo getItem = collection.GetType()\n                    .GetMethods(BindingFlags.Public | BindingFlags.Instance)\n                    .FirstOrDefault(method =>\n                    {\n                        if (!string.Equals(\n                                method.Name,\n                                "get_Item",\n                                StringComparison.Ordinal))\n                            return false;\n                        ParameterInfo[] parameters = method.GetParameters();\n                        return parameters.Length == 1 &&\n                            IsIntegral(parameters[0].ParameterType);\n                    });\n\n                for (int index = 0; index < count; index++)\n                {\n                    object item = null;\n                    if (indexer != null)\n                    {\n                        Type indexType =\n                            indexer.GetIndexParameters()[0].ParameterType;\n                        item = indexer.GetValue(\n                            collection,\n                            new[]\n                            {\n                                Convert.ChangeType(\n                                    index,\n                                    indexType,\n                                    CultureInfo.InvariantCulture)\n                            });\n                    }\n                    else if (getItem != null)\n                    {\n                        Type indexType =\n                            getItem.GetParameters()[0].ParameterType;\n                        item = getItem.Invoke(\n                            collection,\n                            new[]\n                            {\n                                Convert.ChangeType(\n                                    index,\n                                    indexType,\n                                    CultureInfo.InvariantCulture)\n                            });\n                    }\n                    if (item != null) result.Add(item);\n                }\n            }\n            catch\n            {\n                result.Clear();\n            }\n            return result;\n        }\n\n        private static void CollectStyleIds(\n            object value,\n            Transaction transaction,\n            int depth,\n            ISet<object> visited,\n            ISet<ObjectId> result)\n        {\n            if (value == null || value is string || depth > 8) return;\n\n            ObjectId directId = ObjectId.Null;\n            if (value is ObjectId)\n                directId = (ObjectId)value;\n            else\n            {\n                DBObject databaseObject = value as DBObject;\n                if (databaseObject != null) directId = databaseObject.ObjectId;\n            }\n\n            if (!directId.IsNull)\n            {\n                StyleBase style = OpenStyle(directId, transaction);\n                if (style != null) result.Add(directId);\n                return;\n            }\n\n            Type type = value.GetType();\n            if (type.IsPrimitive || type.IsEnum || value is decimal)\n                return;\n            if (visited.Contains(value)) return;\n            visited.Add(value);\n\n            IList<object> items = Enumerate(value);\n            foreach (object item in items)\n                CollectStyleIds(item, transaction, depth + 1, visited, result);\n            if (items.Count > 0) return;\n\n            PropertyInfo[] properties;\n            try\n            {\n                properties = type.GetProperties(\n                    BindingFlags.Public | BindingFlags.Instance);\n            }\n            catch\n            {\n                return;\n            }\n\n            foreach (PropertyInfo property in properties)\n            {\n                if (!property.CanRead ||\n                    property.GetIndexParameters().Length != 0 ||\n                    !ShouldTraverse(property.Name, depth))\n                    continue;\n                object child;\n                try\n                {\n                    child = property.GetValue(value, null);\n                }\n                catch\n                {\n                    continue;\n                }\n                CollectStyleIds(\n                    child,\n                    transaction,\n                    depth + 1,\n                    visited,\n                    result);\n            }\n        }\n\n        private static StyleBase OpenStyle(\n            ObjectId id,\n            Transaction transaction)\n        {\n            if (id.IsNull || id.IsErased || transaction == null) return null;\n            try\n            {\n                return transaction.GetObject(\n                    id,\n                    OpenMode.ForRead,\n                    false) as StyleBase;\n            }\n            catch\n            {\n                return null;\n            }\n        }\n\n        private static object ReadPropertyPath(object value, string path)\n        {\n            object current = value;\n            foreach (string part in (path ?? string.Empty).Split(\'.\'))\n            {\n                current = ReadProperty(current, part);\n                if (current == null) return null;\n            }\n            return current;\n        }\n\n        private static object ReadProperty(object value, string propertyName)\n        {\n            if (value == null) return null;\n            try\n            {\n                PropertyInfo property = value.GetType().GetProperty(\n                    propertyName,\n                    BindingFlags.Public | BindingFlags.Instance);\n                return property == null ||\n                    property.GetIndexParameters().Length != 0\n                    ? null\n                    : property.GetValue(value, null);\n            }\n            catch\n            {\n                return null;\n            }\n        }\n\n        private static bool ShouldTraverse(string propertyName, int depth)\n        {\n            if (depth == 0) return true;\n            string name = (propertyName ?? string.Empty).ToUpperInvariant();\n            return name.Contains("STYLE") ||\n                name.Contains("LABEL") ||\n                name.Contains("BAND") ||\n                name.Contains("RULE") ||\n                name.Contains("TABLE") ||\n                name.Contains("ITEM");\n        }\n\n        private static bool IsIntegral(Type type)\n        {\n            Type value = Nullable.GetUnderlyingType(type) ?? type;\n            return value == typeof(byte) ||\n                value == typeof(sbyte) ||\n                value == typeof(short) ||\n                value == typeof(ushort) ||\n                value == typeof(int) ||\n                value == typeof(uint) ||\n                value == typeof(long) ||\n                value == typeof(ulong);\n        }\n\n        private static bool LooksLikeRuntimeClassName(string value)\n        {\n            string text = (value ?? string.Empty).Trim();\n            return text.StartsWith("AeccDb", StringComparison.OrdinalIgnoreCase) ||\n                text.StartsWith("AecDb", StringComparison.OrdinalIgnoreCase) ||\n                text.StartsWith("AcDb", StringComparison.OrdinalIgnoreCase);\n        }\n\n        private sealed class ReferenceComparer : IEqualityComparer<object>\n        {\n            internal static readonly ReferenceComparer Instance =\n                new ReferenceComparer();\n\n            public new bool Equals(object left, object right)\n            {\n                return ReferenceEquals(left, right);\n            }\n\n            public int GetHashCode(object value)\n            {\n                return RuntimeHelpers.GetHashCode(value);\n            }\n        }\n    }\n}\n'
VALIDATOR_SOURCE = '#!/usr/bin/env python3\n"""Validate strict Civil 3D style discovery and automatic sewer labels."""\n\nfrom pathlib import Path\nimport re\nimport sys\n\nROOT = Path(__file__).resolve().parents[1]\nCIVIL = ROOT / "src" / "CE.Tools.Civil3D"\nHELPER = CIVIL / "CivilStyleCatalogV2.cs"\nPROJECT = CIVIL / "ProjectStyleCenterCommands.cs"\nDISCOVERY = CIVIL / "CivilStyleDiscovery.cs"\nSEWER = CIVIL / "SewerProductionCommands.cs"\nLABELS = CIVIL / "SewerNetworkLabelCommands.cs"\nWORKFLOW = ROOT / ".github" / "workflows" / "core-tests.yml"\n\nerrors: list[str] = []\n\nfor path in (HELPER, PROJECT, DISCOVERY, SEWER, LABELS, WORKFLOW):\n    if not path.exists():\n        errors.append(f"Missing required file: {path.relative_to(ROOT)}")\n\nhelper = HELPER.read_text(encoding="utf-8") if HELPER.exists() else ""\nproject = PROJECT.read_text(encoding="utf-8") if PROJECT.exists() else ""\ndiscovery = DISCOVERY.read_text(encoding="utf-8") if DISCOVERY.exists() else ""\nsewer = SEWER.read_text(encoding="utf-8") if SEWER.exists() else ""\nlabels = LABELS.read_text(encoding="utf-8") if LABELS.exists() else ""\nworkflow = WORKFLOW.read_text(encoding="utf-8") if WORKFLOW.exists() else ""\n\nrequired_helper_markers = (\n    "internal static class CivilStyleCatalogV2",\n    "StyleBase style = OpenStyle",\n    \'LooksLikeRuntimeClassName\',\n    \'"LabelStyles.PipeLabelStyles.PlanProfileLabelStyles"\',\n    \'"LabelStyles.StructureLabelStyles.LabelStyles"\',\n    \'"LabelSetStyles.AlignmentLabelSetStyles"\',\n    \'"LabelSetStyles.ProfileLabelSetStyles"\',\n    \'"ProfileViewBandSetStyles"\',\n    \'"PipeRuleSetStyles"\',\n    \'"StructureRuleSetStyles"\',\n    \'"SectionViewBandSetStyles"\',\n    \'"CorridorStyles"\',\n    \'"AssemblyStyles"\',\n    \'"CodeSetStyles"\',\n)\nfor marker in required_helper_markers:\n    if marker not in helper:\n        errors.append(f"Strict style catalogue is missing marker: {marker}")\n\nfor marker in (\n    \'"Alignment Label Style"\',\n    \'"Profile Label Style"\',\n    \'"Profile View Band Set Style"\',\n    \'"Pipe Rule Set"\',\n    \'"Structure Rule Set"\',\n    \'"Section Label Set Style"\',\n    \'"Section View Band Set Style"\',\n    \'"Pipe Table Style"\',\n    \'"Structure Table Style"\',\n):\n    if marker not in project:\n        errors.append(f"Project Style Centre is missing category: {marker}")\n\nif ("CivilStyleCatalogV2.ReadProjectCatalogue(" not in project or\n        "SelectionKeys" not in project):\n    errors.append("Project Style Centre is not using strict typed style discovery")\n\nif "value as StyleBase" not in discovery:\n    errors.append("Named Objects Dictionary fallback is not restricted to StyleBase")\n\nif "ProductionStyleCatalog.ReadNames(" in sewer:\n    errors.append("Sewer Settings still uses the legacy style catalogue")\nif "CivilStyleCatalogV2.ReadNames(" not in sewer:\n    errors.append("Sewer Settings is not using strict typed style discovery")\n\nfor marker in (\n    \'pipe ? "PlanProfileLabelStyles" : "LabelStyles"\',\n    "TryCreatePipeLabel(",\n    "TryCreateStructureLabel(",\n    "typeof(double)",\n    "typeof(Point3d)",\n    "CivilStyleCatalogV2.ReadObjectIds(collection, transaction)",\n):\n    if marker not in labels:\n        errors.append(f"Automatic sewer label source is missing marker: {marker}")\n\nif "StructureLabelStyles.PlanProfileLabelStyles" in project + labels:\n    errors.append("Invalid structure PlanProfileLabelStyles path remains")\nif re.search(r\'Name\\s*=\\s*"AeccDb\', project + helper + discovery):\n    errors.append("A hard-coded AeccDb runtime class name remains in style choices")\nif "Validate-CivilStyleCatalogueAndSewerLabels.py" not in workflow:\n    errors.append("Core tests do not run the Civil style/sewer-label validator")\n\nfor path, text in (\n    (HELPER, helper),\n    (PROJECT, project),\n    (DISCOVERY, discovery),\n    (SEWER, sewer),\n    (LABELS, labels),\n):\n    if text.count("{") != text.count("}"):\n        errors.append(f"Unbalanced braces: {path.relative_to(ROOT)}")\n    if text.count("(") != text.count(")"):\n        errors.append(f"Unbalanced parentheses: {path.relative_to(ROOT)}")\n\nif errors:\n    print("Civil style catalogue / sewer label validation failed:", file=sys.stderr)\n    for error in errors:\n        print(f"- {error}", file=sys.stderr)\n    raise SystemExit(1)\n\nprint(\n    "Civil style catalogue / sewer label validation passed: typed StyleBase "\n    "choices, label sets, band sets, rule sets and explicit pipe/structure "\n    "label creation are wired."\n)\n'
SELECTION_BLOCK = '        private static readonly string[] SelectionKeys =\n        {\n            "Alignment Style",\n            "Alignment Label Set Style",\n            "Alignment Label Style",\n            "Profile Style",\n            "Profile Label Set Style",\n            "Profile Label Style",\n            "Profile View Style",\n            "Profile View Band Set Style",\n            "Profile View Label Style",\n            "Surface Style",\n            "Surface Label Style",\n            "Point Style",\n            "Point Label Style",\n            "Feature Line Style",\n            "Feature Line Label Style",\n            "Parcel Style",\n            "Parcel Label Style",\n            "Catchment Style",\n            "Catchment Label Style",\n            "Grading Style",\n            "Corridor Style",\n            "Code Set Style",\n            "Assembly Style",\n            "Pipe Style",\n            "Pipe Label Style",\n            "Structure Style",\n            "Structure Label Style",\n            "Pipe Rule Set",\n            "Structure Rule Set",\n            "Pressure Pipe Style",\n            "Pressure Pipe Label Style",\n            "Fitting Style",\n            "Fitting Label Style",\n            "Appurtenance Style",\n            "Appurtenance Label Style",\n            "Section Style",\n            "Section Label Set Style",\n            "Section Label Style",\n            "Section View Style",\n            "Section View Band Set Style",\n            "Section View Label Style",\n            "Sample Line Style",\n            "Sample Line Label Style",\n            "Mass Haul View Style",\n            "Mass Haul Line Style",\n            "Marker Style",\n            "Alignment Table Style",\n            "Parcel Table Style",\n            "Point Table Style",\n            "Pipe Table Style",\n            "Structure Table Style",\n            "Surface Table Style"\n        };'
CATALOG_METHOD = '        private static Dictionary<string, List<string>> ReadCivilStyleCatalogue(\n            Document document)\n        {\n            return CivilStyleCatalogV2.ReadProjectCatalogue(\n                document,\n                SelectionKeys);\n        }'
MAP_CATEGORY_METHOD = '        private static string MapCategory(string source)\n        {\n            string value = (source ?? string.Empty)\n                .Replace("_", string.Empty)\n                .Replace(" ", string.Empty)\n                .ToUpperInvariant();\n\n            if (value.Contains("SECTIONVIEW") && value.Contains("BAND"))\n                return "Section View Band Set Style";\n            if (value.Contains("PROFILEVIEW") && value.Contains("BAND"))\n                return "Profile View Band Set Style";\n            if (value.Contains("SECTION") && value.Contains("LABELSET"))\n                return "Section Label Set Style";\n            if (value.Contains("PROFILE") && value.Contains("LABELSET"))\n                return "Profile Label Set Style";\n            if (value.Contains("ALIGNMENT") && value.Contains("LABELSET"))\n                return "Alignment Label Set Style";\n            if (value.Contains("STRUCTURERULE"))\n                return "Structure Rule Set";\n            if (value.Contains("PIPERULE"))\n                return "Pipe Rule Set";\n            if (value.Contains("STRUCTURE") && value.Contains("LABEL"))\n                return "Structure Label Style";\n            if (value.Contains("PRESSURE") && value.Contains("PIPE") &&\n                value.Contains("LABEL"))\n                return "Pressure Pipe Label Style";\n            if (value.Contains("PIPE") && value.Contains("LABEL"))\n                return "Pipe Label Style";\n            if (value.Contains("SECTIONVIEW") && value.Contains("LABEL"))\n                return "Section View Label Style";\n            if (value.Contains("SECTION") && value.Contains("LABEL"))\n                return "Section Label Style";\n            if (value.Contains("PROFILEVIEW") && value.Contains("LABEL"))\n                return "Profile View Label Style";\n            if (value.Contains("PROFILE") && value.Contains("LABEL"))\n                return "Profile Label Style";\n            if (value.Contains("ALIGNMENT") && value.Contains("LABEL"))\n                return "Alignment Label Style";\n            if (value.Contains("SURFACE") && value.Contains("LABEL"))\n                return "Surface Label Style";\n            if (value.Contains("POINT") && value.Contains("LABEL"))\n                return "Point Label Style";\n            if (value.Contains("FEATURELINE") && value.Contains("LABEL"))\n                return "Feature Line Label Style";\n            if (value.Contains("PARCEL") && value.Contains("LABEL"))\n                return "Parcel Label Style";\n            if (value.Contains("CATCHMENT") && value.Contains("LABEL"))\n                return "Catchment Label Style";\n            if (value.Contains("PRESSURE") && value.Contains("PIPE"))\n                return "Pressure Pipe Style";\n            if (value.Contains("APPURTENANCE") && value.Contains("LABEL"))\n                return "Appurtenance Label Style";\n            if (value.Contains("APPURTENANCE"))\n                return "Appurtenance Style";\n            if (value.Contains("FITTING") && value.Contains("LABEL"))\n                return "Fitting Label Style";\n            if (value.Contains("FITTING"))\n                return "Fitting Style";\n            if (value.Contains("STRUCTURETABLE"))\n                return "Structure Table Style";\n            if (value.Contains("PIPETABLE"))\n                return "Pipe Table Style";\n            if (value.Contains("SURFACETABLE"))\n                return "Surface Table Style";\n            if (value.Contains("POINTTABLE"))\n                return "Point Table Style";\n            if (value.Contains("PARCELTABLE"))\n                return "Parcel Table Style";\n            if (value.Contains("ALIGNMENTTABLE"))\n                return "Alignment Table Style";\n            if (value.Contains("STRUCTURE"))\n                return "Structure Style";\n            if (value.Contains("PIPE"))\n                return "Pipe Style";\n            if (value.Contains("CODESET"))\n                return "Code Set Style";\n            if (value.Contains("ASSEMBLY"))\n                return "Assembly Style";\n            if (value.Contains("CORRIDOR"))\n                return "Corridor Style";\n            if (value.Contains("SECTIONVIEW"))\n                return "Section View Style";\n            if (value.Contains("SECTION"))\n                return "Section Style";\n            if (value.Contains("PROFILEVIEW"))\n                return "Profile View Style";\n            if (value.Contains("PROFILE"))\n                return "Profile Style";\n            if (value.Contains("ALIGNMENT"))\n                return "Alignment Style";\n            if (value.Contains("FEATURELINE"))\n                return "Feature Line Style";\n            if (value.Contains("POINT"))\n                return "Point Style";\n            if (value.Contains("SURFACE"))\n                return "Surface Style";\n            if (value.Contains("PARCEL"))\n                return "Parcel Style";\n            if (value.Contains("CATCHMENT"))\n                return "Catchment Style";\n            if (value.Contains("GRADING"))\n                return "Grading Style";\n            if (value.Contains("SAMPLELINE"))\n                return "Sample Line Style";\n            if (value.Contains("MASSHAULVIEW"))\n                return "Mass Haul View Style";\n            if (value.Contains("MASSHAULLINE"))\n                return "Mass Haul Line Style";\n            if (value.Contains("MARKER"))\n                return "Marker Style";\n            return string.Empty;\n        }'
READ_LABEL_COLLECTION = '        private static object ReadLabelStyleCollection(\n            CivilDocument civilDocument,\n            bool pipe)\n        {\n            object styles = ReadProperty(civilDocument, "Styles");\n            object labelStyles = ReadProperty(styles, "LabelStyles");\n            object family = ReadProperty(\n                labelStyles,\n                pipe ? "PipeLabelStyles" : "StructureLabelStyles");\n            if (family == null) return null;\n\n            // Civil 3D exposes pipe plan/profile labels under\n            // PipeLabelStylesRoot.PlanProfileLabelStyles, while structure plan\n            // labels are under StructureLabelStylesRoot.LabelStyles.\n            object exact = ReadProperty(\n                family,\n                pipe ? "PlanProfileLabelStyles" : "LabelStyles");\n            if (exact != null) return exact;\n\n            // Some builds expose a PlanLabelStyles compatibility property.\n            return ReadProperty(family, "PlanLabelStyles") ?? family;\n        }'
RESOLVE_STYLE_METHOD = '        private static ObjectId ResolveStyleId(\n            object collection,\n            string requested,\n            Transaction transaction)\n        {\n            IList<ObjectId> ids =\n                CivilStyleCatalogV2.ReadObjectIds(collection, transaction);\n            ObjectId first = ids.Count == 0 ? ObjectId.Null : ids[0];\n            bool useFirst = string.IsNullOrWhiteSpace(requested) ||\n                string.Equals(\n                    requested,\n                    CivilStyleCatalogV2.DrawingDefault,\n                    StringComparison.OrdinalIgnoreCase);\n            if (useFirst) return first;\n\n            foreach (ObjectId id in ids)\n            {\n                try\n                {\n                    DBObject style = transaction.GetObject(\n                        id,\n                        OpenMode.ForRead,\n                        false);\n                    string name = Convert.ToString(\n                        ReadProperty(style, "Name"),\n                        CultureInfo.CurrentCulture);\n                    if (string.Equals(\n                            name,\n                            requested,\n                            StringComparison.OrdinalIgnoreCase))\n                        return id;\n                }\n                catch\n                {\n                    // Try the next real Civil style.\n                }\n            }\n            return first;\n        }'
LABEL_WRAPPERS = '        private static bool TryCreatePipeLabel(\n            Type labelType,\n            ObjectId pipeId,\n            ObjectId styleId,\n            Transaction transaction)\n        {\n            if (labelType == null || pipeId.IsNull || styleId.IsNull)\n                return false;\n\n            foreach (MethodInfo method in labelType.GetMethods(\n                BindingFlags.Public | BindingFlags.Static)\n                .Where(candidate => string.Equals(\n                    candidate.Name,\n                    "Create",\n                    StringComparison.Ordinal)))\n            {\n                ParameterInfo[] parameters = method.GetParameters();\n                if (parameters.Length != 3 ||\n                    parameters[0].ParameterType != typeof(ObjectId) ||\n                    parameters[1].ParameterType != typeof(double) ||\n                    parameters[2].ParameterType != typeof(ObjectId))\n                    continue;\n                if (TryInvokeCreate(\n                        method,\n                        new object[] { pipeId, 0.5, styleId },\n                        transaction))\n                    return true;\n            }\n\n            return TryCreateCompatibleLabel(\n                labelType,\n                pipeId,\n                styleId,\n                transaction);\n        }\n\n        private static bool TryCreateStructureLabel(\n            Type labelType,\n            ObjectId structureId,\n            ObjectId styleId,\n            Transaction transaction)\n        {\n            if (labelType == null || structureId.IsNull || styleId.IsNull)\n                return false;\n\n            Point3d location = ReadFeaturePoint(structureId, transaction);\n            foreach (MethodInfo method in labelType.GetMethods(\n                BindingFlags.Public | BindingFlags.Static)\n                .Where(candidate => string.Equals(\n                    candidate.Name,\n                    "Create",\n                    StringComparison.Ordinal)))\n            {\n                ParameterInfo[] parameters = method.GetParameters();\n                if (parameters.Length != 3 ||\n                    parameters[0].ParameterType != typeof(ObjectId) ||\n                    parameters[1].ParameterType != typeof(ObjectId) ||\n                    parameters[2].ParameterType != typeof(Point3d))\n                    continue;\n                if (TryInvokeCreate(\n                        method,\n                        new object[] { structureId, styleId, location },\n                        transaction))\n                    return true;\n            }\n\n            return TryCreateCompatibleLabel(\n                labelType,\n                structureId,\n                styleId,\n                transaction);\n        }\n\n        private static bool TryInvokeCreate(\n            MethodInfo method,\n            object[] arguments,\n            Transaction transaction)\n        {\n            try\n            {\n                object created = method.Invoke(null, arguments);\n                ObjectId id = created is ObjectId\n                    ? (ObjectId)created\n                    : ReadObjectIdProperty(created, "ObjectId", "Id");\n                if (id.IsNull) return false;\n                transaction.GetObject(id, OpenMode.ForRead, false);\n                return true;\n            }\n            catch\n            {\n                return false;\n            }\n        }\n\n'


def read(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8", newline="\n")


def replace_once(path: Path, old: str, new: str, label: str) -> None:
    text = read(path)
    if new in text:
        return
    if old not in text:
        raise RuntimeError(f"{label}: expected source text was not found in {path}")
    write(path, text.replace(old, new, 1))


def replace_regex(
    path: Path,
    pattern: str,
    replacement: str,
    label: str,
    flags: int = re.MULTILINE | re.DOTALL,
) -> None:
    text = read(path)
    if replacement in text:
        return
    updated, count = re.subn(pattern, replacement, text, count=1, flags=flags)
    if count != 1:
        raise RuntimeError(
            f"{label}: expected one match in {path}, found {count}"
        )
    write(path, updated)


